import {WorkerClient} from '../services/worker-client.js';
import {readUpload} from '../services/import.js';
import {t,fmt,getLocale,setLocale,errorText} from '../i18n/locale.js';
import {renderChart,exportChart} from '../charts/render.js';
import {OperationForm} from './operation-form.js';
import {esc,$,$$,icon,download,asCSV,localProject} from './utils.js';
const BASE=import.meta.env.BASE_URL;
const CHARTS=['scatter','bar','line','histogram','box','correlation','heatmap','area','distribution','court','missing'];
const AGGS=['mean','sum','median','min','max','std','count','size','nunique'];
const NBA_LABELS={players:['球员名单','Players'],teams:['球队字典','Teams'],games:['比赛赛程','Games'],player_game_stats:['球员逐场统计','Player game statistics'],team_game_stats:['球队逐场统计','Team game statistics'],shots:['逐次投篮','Shots']};
const bilingual=(zh,en)=>getLocale()==='zh-CN'?zh:en;
const and=args=>args.length===0?null:args.length===1?args[0]:{op:'and',args};
export class App{
  constructor(root){this.root=root;this.worker=new WorkerClient();this.route='overview';this.snapshot={nodes:[],tables:[]};this.config={x:'pts',y:'ast',category:'player_name',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};this.channels={};this.offset=0;this.pageSize=50;this.tab='dataPreview';this.chartType='scatter';this.nbaTab='playerTab';this.nbaNodes={};this.busyCount=0;this.queryVersion=0;this.draft=null;this.loaded=new Set();this.importData=null;this.form=null;this.lastError=null;this.detailField=null;this.editNode=null;}
  async start(){try{setLocale(localStorage.getItem('nba-datalab-locale')??'zh-CN');}catch{setLocale('zh-CN');}this.render();
    window.addEventListener('hashchange',()=>this.safe(()=>this.navigate()));
    this.root.onclick=event=>this.click(event);
    this.root.onchange=event=>this.change(event);
    this.root.oninput=event=>{if(event.target.id==='field-search')this.filterFields(event.target.value);};
    this.root.ondragover=event=>{if(event.dataTransfer.types.includes('Files'))event.preventDefault();};
    this.root.ondrop=event=>{event.preventDefault();const file=event.dataTransfer.files[0];if(file)this.safe(()=>this.openImport(file));};
    await this.run(async()=>{const response=await fetch(`${BASE}data/nba/2025-26-nov/manifest.json`);if(!response.ok)throw new Error('LOAD_FAILED');this.manifest=await response.json();await this.loadNBA(['players','teams','games','team_game_stats','player_game_stats']);this.overview=await this.worker.call('overview');this.playerNames=new Map((await this.worker.call('analysisExport',{id:'source:nba_players',kind:'rows'})).map(r=>[r.player_id,r.player_name]));await this.worker.call('select',{id:'source:nba_player_game_stats'});await this.worker.retain();await this.navigate();});
  }
  async run(fn){this.busyCount++;this.busy();try{return await fn();}finally{this.busyCount--;this.busy();}}
  safe(fn){return this.run(fn).catch(error=>this.fail(error));}
  busy(){const el=$('#busy');if(el){el.hidden=this.busyCount===0;$('#busy-text').textContent=t('working');}this.root.setAttribute('aria-busy',String(this.busyCount>0));}
  fail(error){if(error.code==='CANCELLED'||error.message==='CANCELLED'){this.toast(errorText({code:'CANCELLED'}));return;}this.lastError=error;this.toast(`${errorText(error)}${error.code||error.message?` (${error.code??error.message})`:''}`,true);console.error('[DataLab]',error.code??error.message,error.details??'');}
  toast(message,error=false){let host=$('#toast');if(!host){host=document.createElement('div');host.id='toast';host.setAttribute('role','status');document.body.append(host);}host.className=error?'toast error':'toast';host.textContent=message;clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>host.classList.remove('toast'),error?10000:4000);}
  name(table){const id=typeof table==='string'?table:table.id;if(id.startsWith('source:nba_'))return NBA_LABELS[id.slice(11)]?.[getLocale()==='zh-CN'?0:1]??id;const node=this.snapshot.nodes?.find(n=>n.id===id);return node?.kind==='operation'?`${id.split(':')[1].padStart(2,'0')} · ${t(node.spec.type)}`:table.provenance?.fileName??id.replace('source:','');}
  async loadNBA(ids){const missing=ids.filter(id=>!this.loaded.has(id));const texts=await Promise.all(missing.map(async id=>{const meta=this.manifest.tables.find(t=>t.id===id),response=await fetch(`${BASE}data/nba/2025-26-nov/${meta.file}`);if(!response.ok)throw new Error('LOAD_FAILED');const text=await response.text();const bytes=new TextEncoder().encode(text),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(b=>b.toString(16).padStart(2,'0')).join('');if(hash!==meta.sha256)throw new Error('SOURCE_MISMATCH');return {id,text,meta};}));
    for(const {id,text,meta}of texts){try{await this.worker.call('import',{text,options:{id:`nba_${id}`,fileName:`NBA · ${id}`,format:'csv',types:Object.fromEntries(meta.columns.map(c=>[c.name,c.type]))}});}catch(error){if(error.code!=='DATASET_EXISTS')throw error;}this.loaded.add(id);}
  }
  async navigate(){const route=location.hash.replace(/^#\/?/,'').split('?')[0]||'overview';this.route=['overview','nba','studio','gallery'].includes(route)?route:'overview';this.form=null;if(this.route==='nba'){await this.activateNBA();if(this.pendingNBASelection){Object.assign(this.channels,this.pendingNBASelection);this.pendingNBASelection=null;await this.analyze();}}else if(this.route==='overview')this.render();else await this.analyze();window.scrollTo(0,0);}
  goto(route){if(this.route===route)this.safe(()=>this.navigate());else location.hash=`/${route}`;}
  selection(){return and(Object.values(this.channels).filter(Boolean));}
  preserveDraft(){if(this.form)this.draft=this.form.remember();}
  async analyze(){if(this.chartType==='court'){this.config.x='x_legacy';this.config.y='y_legacy';}this.preserveDraft();const version=++this.queryVersion;const snapshot=await this.worker.call('analyze',{config:{...this.config,correlation:true},selection:this.selection(),offset:this.offset,limit:this.pageSize});if(version!==this.queryVersion)return;this.snapshot=snapshot;if(this.chartType==='court'&&!this.canCourt())this.chartType='scatter';this.loaded=new Set(snapshot.nodes.filter(n=>n.kind==='source'&&n.sourceId.startsWith('nba_')).map(n=>n.sourceId.slice(4)));if(snapshot.charts)for(const [key,c]of Object.entries(snapshot.charts.fields))if(c)this.config[key]=c.id;this.render();}
  async mutate(action,payload={}){this.preserveDraft();await this.worker.call(action,payload);this.channels={};this.offset=0;this.preview=null;await this.worker.retain();await this.analyze();}
  async activateNBA(){await this.loadNBA(this.nbaTab==='courtTab'?['shots']:['teamTab','trendTab'].includes(this.nbaTab)?['team_game_stats']:['player_game_stats']);this.channels={};this.offset=0;this.draft=null;this.editNode=null;
    if(this.nbaTab==='courtTab'){await this.loadNBA(['shots']);await this.worker.call('select',{id:'source:nba_shots'});this.chartType='court';this.config={x:'x_legacy',y:'y_legacy',category:'made',date:'game_date',metric:'shot_distance',aggregate:'mean',correlation:true};}
    else if(['teamTab','trendTab'].includes(this.nbaTab)){await this.worker.call('select',{id:'source:nba_team_game_stats'});this.chartType=this.nbaTab==='trendTab'?'line':'bar';this.config={x:'pts',y:'ast',category:'team_abbr',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};}
    else{await this.worker.call('select',{id:'source:nba_player_game_stats'});this.chartType='scatter';this.config={x:'pts',y:'ast',category:'player_name',date:'game_date',metric:'pts',aggregate:'mean',correlation:true};const state=await this.worker.call('snapshot');if(this.nbaNodes.played&&state.nodes.some(n=>n.id===this.nbaNodes.played&&n.inputs?.[0]==='source:nba_player_game_stats'&&n.spec?.params?.predicate?.field==='played'&&n.spec.params.predicate.value===true))await this.worker.call('select',{id:this.nbaNodes.played});else{const result=await this.worker.call('commit',{spec:{type:'filter',params:{predicate:{op:'eq',field:'played',value:true}}}});this.nbaNodes.played=result.activeId;}}
    await this.analyze();await this.worker.retain();this.nbaValues=await this.worker.call('values',{field:this.nbaTab==='courtTab'?'player_id':this.nbaTab==='playerTab'?'player_name':'team_abbr'});this.render();
  }
  header(){return `<header class="site-header"><a class="brand" href="#/overview" aria-label="NBA DataLab"><span class="brand-ball"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="16" cy="16" r="13"/><path d="M3 16h26M16 3v26M7 6q18 10 0 20M25 6Q7 16 25 26"/></svg></span><span>NBA <strong>DataLab</strong><small>${t('brandSub')}</small></span></a><nav aria-label="${bilingual('主导航','Main navigation')}">${['overview','nba','studio','gallery'].map((key,i)=>`<a href="#/${key}" class="${this.route===key?'active':''}" ${this.route===key?'aria-current="page"':''}><span class="nav-index">0${i+1}</span>${t(key)}</a>`).join('')}</nav><div class="header-tools"><button class="lang" data-action="locale" aria-label="${bilingual('切换为英文','Switch to Chinese')}">${getLocale()==='zh-CN'?'EN / 中':'中 / EN'}</button><button class="button primary upload-button" data-action="upload">${icon('upload')}<span>${t('upload')}</span></button></div></header>`;}
  render(){this.form=null;this.root.innerHTML=`${this.header()}<main id="main-content">${this.route==='overview'?this.overviewHTML():this.route==='studio'?this.studioHTML():this.route==='nba'?this.nbaHTML():this.galleryHTML()}</main><footer class="site-footer"><a href="#/overview">NBA <strong>DataLab</strong></a><span>JavaScript · D3.js · ${t('localPrivacy')}</span><button class="text-button" data-action="about">${t('about')} ↗</button></footer><div id="busy" class="busy" hidden role="status"><span class="spinner"></span><span id="busy-text">${t('working')}</span><button data-action="cancel" class="text-button">${t('cancelTask')}</button></div>`;
    this.busy();if(this.route==='overview')this.drawOverview();else if(this.snapshot.charts){if(this.route==='studio'){this.mountForm();this.drawActiveCharts();this.drawPreview();}else if(this.route==='nba')this.drawActiveCharts();else this.drawGallery();}
  }
  overviewHTML(){const d=this.overview,stats=d?[[d.games,'games','01'],[d.teams,'teams','02'],[d.players,'players','03'],[this.manifest.tables.find(t=>t.id==='shots').rows,'shots','04']]:[[null,'games','01'],[null,'teams','02'],[null,'players','03'],[null,'shots','04']];
    return `<div class="overview page-shell"><section class="hero"><div class="hero-copy"><span class="eyebrow"><i></i>${t('heroKicker')}</span><h1>${t('heroTitle')}</h1><p>${t('heroText')}</p><div class="hero-actions"><button class="button primary" data-action="go-nba">${t('exploreNBA')}${icon()}</button><button class="button secondary" data-action="go-studio">${t('openStudio')}${icon('grid')}</button></div><div class="hero-proof"><span class="avatars"><b>01</b><b>02</b><b>03</b></span><span>${bilingual('筛选 · 洞察 · 复现，每一步都算数','Filter. Discover. Reproduce. Every step counts.')}</span></div></div><div class="hero-visual"><div class="visual-heading"><span><i class="dot"></i> NOV ’25 / COURTSIDE DATA</span><span>NBA ↗</span></div><div class="court-illustration" aria-hidden="true"><svg viewBox="0 0 500 330"><defs><pattern id="grain" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#b6c5b4" stroke-width=".5"/></pattern></defs><rect x="22" y="15" width="456" height="295" rx="5" fill="url(#grain)" stroke="#90a58d"/><path d="M22 162h456M250 15v295" stroke="#9aaf97"/><circle cx="250" cy="162" r="48" fill="none" stroke="#90a58d"/><path d="M150 15v87h200V15M190 15v87h120V15M150 310v-87h200v87M190 310v-87h120v87" fill="none" stroke="#90a58d"/><path d="M40 15v75a210 210 0 0 0 420 0V15M40 310v-75a210 210 0 0 1 420 0v75" fill="none" stroke="#90a58d"/><circle cx="250" cy="42" r="5" fill="none" stroke="#68876c"/><circle cx="250" cy="283" r="5" fill="none" stroke="#68876c"/></svg><span class="floating-metric"><small>${t('avgTeamPts')}</small><strong>${fmt(d?.points,1)}<em> PTS</em></strong><span>2025—26 / NOVEMBER</span></span><span class="floating-label">THE GAME,<br>IN NUMBERS.</span><span class="illustration-note">${bilingual('球场示意 · 下方图表为真实计算','Court illustration · real analyses below')}</span></div></div></section><section class="snapshot-strip" aria-label="${t('liveSnapshot')}">${stats.map(([value,label,n])=>`<div><span class="stat-index">${n}</span><strong>${fmt(value,0)}</strong><span>${t(label)}</span></div>`).join('')}<p><i class="dot"></i>${t('dataWindow')}<button class="text-button" data-action="about">${t('source')} ↗</button></p></section><section class="overview-analysis"><article class="card trend-card"><div class="section-heading"><div><span class="eyebrow">01 / THE BIG PICTURE</span><h2>${t('dailyPoints')}</h2><p>${t('dailyPointsSub')}</p></div><span class="pill">${d?fmt(d.points,1):'—'} PTS</span></div><div id="overview-trend" class="chart-host"></div></article><article class="card leaders-card"><div class="section-heading"><div><span class="eyebrow">02 / PLAYMAKERS</span><h2>${t('leaders')}</h2></div></div><div class="leader-list">${d?.leaders.map((r,i)=>`<button class="leader-row" data-leader="${esc(r.player_name)}"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="player-monogram">${esc(r.player_name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</span><span class="leader-name">${esc(r.player_name)}<small>${r.GP} ${bilingual('场出场','appearances')}</small></span><strong>${fmt(r.PPG,1)}<small>PPG</small></strong></button>`).join('')??`<p class="hint">${t('working')}</p>`}</div></article></section><section class="questions"><div class="section-heading"><div><span class="eyebrow">KEEP YOUR CURIOSITY IN PLAY</span><h2>${t('startQuestion')}</h2></div><span class="hint">${t('snapshotNote')}</span></div><div class="question-grid">${[['questionCompare','questionCompareSub','nba','chart'],['questionSpace','questionSpaceSub','court','filter'],['questionOwn','questionOwnSub','upload','database']].map(([title,sub,action,ico],i)=>`<button class="question-card" data-question="${action}"><span class="question-top">${icon(ico)}<small>0${i+1}</small></span><strong>${t(title)}</strong><p>${t(sub)}</p><span class="question-arrow">↗</span></button>`).join('')}</div></section></div>`;
  }
  drawOverview(){if(!this.overview)return;renderChart($('#overview-trend'),'area',this.overview.charts,{locale:getLocale(),title:t('dailyPoints'),onSelection:(_channel,predicate)=>{this.nbaTab='trendTab';this.pendingNBASelection={time:predicate};this.goto('nba');}});}
  intro(title,text,actions=''){return `<div class="page-intro"><div><span class="eyebrow">NBA DATALAB / ${this.route.toUpperCase()}</span><h1>${t(title)}</h1><p>${t(text)}</p></div>${actions}</div>`;}
  selectionHTML(){const selection=this.selection();return `<div class="selection-strip ${selection?'has-selection':''}" title="${esc(selection?this.predicateLabel(selection):'')}"><span>${icon('filter')} ${selection?`${t('selected')} <strong>${fmt(this.snapshot.rows,0)} / ${fmt(this.snapshot.committedRows,0)}</strong> · ${t('selectionPending')} <span class="selection-chips">${Object.entries(this.channels).filter(([,v])=>v).map(([key,value])=>`<button class="selection-chip" data-clear-channel="${key}" title="${esc(this.predicateLabel(value))}">${esc(this.predicateLabel(value))} ×</button>`).join('')}</span>`:t('selectionHint')}</span><div><button class="text-button" data-action="clear-selection" ${selection?'':'disabled'}>${t('clearSelection')}</button><button class="button small primary" data-action="apply-selection" ${selection?'':'disabled'}>${t('applySelection')}</button></div></div>`;}
  datasetPanel(){const tables=this.snapshot.tables??[],cols=this.snapshot.columns??[];return `<aside class="data-sidebar"><div class="pane-heading"><h2>${icon('database')}${t('data')}</h2><button class="icon-button" data-action="upload" aria-label="${t('upload')}">+</button></div><div class="dataset-list">${tables.map(table=>`<div class="dataset-item ${table.id===this.snapshot.activeId?'active':''}"><button data-node="${esc(table.id)}" title="${esc(table.provenance?.fileName??table.id)}">${icon(table.id.startsWith('source:')?'database':'chart')}<span>${esc(this.name(table))}<small>${fmt(table.rows,0)} ${t('rows')}</small></span></button>${table.id.startsWith('source:')?`<button class="remove-dataset" data-remove-source="${esc(table.id.slice(7))}" aria-label="${t('remove')}">×</button>`:''}</div>`).join('')}</div><button class="text-button add-nba" data-action="add-nba">+ ${t('addNBA')}</button><div class="field-heading"><h3>${t('fields')} <span>${cols.length}</span></h3><input type="search" id="field-search" placeholder="${t('searchFields')}" aria-label="${t('searchFields')}"></div><div class="fields-list">${cols.map(c=>`<button class="field-item" data-field="${esc(c.id)}" data-name="${esc(c.name.toLowerCase())}"><span class="type-icon">${['number','integer'].includes(c.type)?'#':['date','datetime'].includes(c.type)?'◷':c.type==='boolean'?'◐':'Aa'}</span><span>${esc(c.name)}<small>${esc(c.type)}</small></span><span class="field-arrow">↗</span></button>`).join('')}</div><div class="privacy-note">${icon('check')}<span>${t('localPrivacy')}<small>50 MiB · 100k ${t('rows')} · 200 ${t('columns')}</small></span></div></aside>`;}
  statsHTML(){const s=this.snapshot,missing=s.profile?.columns.reduce((n,c)=>n+c.missing,0);return `<div class="work-stats">${[[s.rows,'rows'],[s.columns?.length,'columns'],[missing,'missing']].map(([v,key])=>`<div><small>${t(key)}</small><strong>${fmt(v,0)}</strong></div>`).join('')}${s.charts?.shots?`<div><small>${t('fieldGoal')}</small><strong>${fmt(s.charts.shots.pct===null?null:s.charts.shots.pct*100,1)}<em>%</em></strong><span>${fmt(s.charts.shots.made,0)} / ${fmt(s.charts.shots.attempts,0)}</span></div>`:`<div><small>${t('quality')}</small><strong>${s.rows&&s.columns?.length?fmt(100*(1-missing/(s.rows*s.columns.length)),1):'—'}<em>%</em></strong><span>${t('valid')}</span></div>`}</div>`;}
  options(columns,value,blank=false){return `${blank?'<option value="">—</option>':''}${columns.map(c=>`<option value="${esc(c.id)}" ${c.id===value||c.name===value?'selected':''}>${esc(c.name)}</option>`).join('')}`;}
  encodings(){const cols=this.snapshot.columns??[],num=cols.filter(c=>['number','integer'].includes(c.type)),dates=cols.filter(c=>['date','datetime'].includes(c.type));return `<details class="encodings"><summary>${t('chartSettings')}<span>＋</span></summary><div class="encoding-grid">${this.chartType==='court'?`<label>${bilingual('空间呈现','Spatial display')}<select data-config="courtMode">${[['points',bilingual('逐次投篮与刷选','Shots and brush')],['frequency',bilingual('区域出手数','Attempts by region')],['rate',bilingual('区域命中率','FG% by region')]].map(([v,label])=>`<option value="${v}" ${v===(this.config.courtMode??'points')?'selected':''}>${label}</option>`).join('')}</select></label>`:''}${[['x','xField',num],['y','yField',num],['category','category',cols],['date','date',dates],['metric','metric',num]].map(([key,label,columns])=>`<label>${t(label)}<select data-config="${key}" ${this.chartType==='court'&&['x','y'].includes(key)?'disabled':''}>${this.options(columns,this.config[key],key==='date')}</select></label>`).join('')}<label>${t('aggregate')}<select data-config="aggregate">${AGGS.map(fn=>`<option value="${fn}" ${fn===this.config.aggregate?'selected':''}>${t(fn)}</option>`).join('')}</select></label><label>${t('bins')}<input type="number" min="4" max="60" data-config="bins" value="${this.config.bins??20}"></label><label>${t('correlation')}<select data-config="corrFields" multiple aria-label="${t('correlation')}">${num.map(c=>`<option value="${esc(c.id)}" ${(this.config.corrFields??num.slice(0,8).map(c=>c.id)).includes(c.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div></details>`;}
  canvasHTML(){return `<article class="card analysis-card"><div class="canvas-heading"><div><span class="eyebrow">EXPLORE THE RELATIONSHIP</span><h2>${t('chart')}</h2></div><select id="chart-type" aria-label="${t('chartType')}">${CHARTS.map(type=>`<option value="${type}" ${type===this.chartType?'selected':''} ${type==='court'&&!this.canCourt()?'disabled':''}>${t(type==='missing'?'missingChart':type)}</option>`).join('')}</select></div>${this.encodings()}<div class="main-chart chart-host" id="main-chart"></div><div class="chart-footnote"><span>${this.snapshot.charts?.pointSample&&(this.chartType==='scatter'||(this.chartType==='court'&&(this.config.courtMode??'points')==='points'))?t('sampleHint'):t('allDataHint')}</span><button class="text-button" data-action="chart-svg">SVG ↓</button><button class="text-button" data-action="chart-png">PNG ↓</button></div>${this.chartType==='court'?`<p class="coordinate-note">${t('coordinateNote')} ${t('fullRange')} · ${t('lowN')}</p>`:''}</article><article class="card distribution-card"><div class="canvas-heading"><h3>${t('distribution')}<span class="muted"> / ${esc(this.snapshot.charts?.fields.x?.name??'')}</span></h3><span class="hint">${t('chartHint')}</span></div><div class="chart-host compact-chart" id="secondary-chart"></div></article>`;}
  tableHTML(records=this.snapshot.records,columns=this.snapshot.columns,sortable=true){if(!columns?.length)return `<p class="empty-state">${t('noDataset')}</p>`;return `<div class="table-scroll"><table><thead><tr><th class="row-number">#</th>${columns.map(c=>`<th>${sortable?`<button data-sort="${esc(c.id)}">${esc(c.name)} <span>↕</span></button>`:esc(c.name)}<small>${esc(c.type)}</small></th>`).join('')}</tr></thead><tbody>${records?.length?records.map((r,i)=>`<tr data-row-id="${esc(this.snapshot.rowIds?.[i]??'')}"><td class="row-number">${this.offset+i+1}</td>${columns.map(c=>`<td class="${r[c.name]===null?'null':typeof r[c.name]==='number'?'numeric':''}" title="${esc(r[c.name]??t('na'))}">${r[c.name]===null?`<span>${t('na')}</span>`:esc(typeof r[c.name]==='number'?fmt(r[c.name],5):r[c.name])}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length+1}"><div class="empty-state"><strong>${t('empty')}</strong><p>${t('emptyHint')}</p></div></td></tr>`}</tbody></table></div>`;}
  profileHTML(){return `<div class="profile-summary"><p class="hint">${t('allDataHint')} · std(ddof=1) · quantile(linear)</p><div class="table-scroll"><table><thead><tr>${['field','type','valid','missing','missingRate','unique','mean','std','min','q1','median','q3','max'].map(key=>`<th>${t(key)}</th>`).join('')}</tr></thead><tbody>${this.snapshot.profile?.columns.map(c=>`<tr><th><button class="text-button" data-field="${esc(c.id)}">${esc(c.name)}</button></th><td>${c.type}</td>${['count','missing','missingRate','unique','mean','std','min','q1','median','q3','max'].map(k=>`<td class="numeric">${k==='missingRate'?fmt(c[k]===null?null:c[k]*100,1)+'%':fmt(c[k],3)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
  resultsHTML(){const s=this.snapshot;return `<article class="card result-card"><div class="result-tabs" role="tablist">${['dataPreview','statistics','pandas'].map(tab=>`<button role="tab" aria-selected="${this.tab===tab}" class="${this.tab===tab?'active':''}" data-tab="${tab}">${t(tab)}</button>`).join('')}<span class="result-version">v${s.version??0} · ${t('allDataHint')}</span></div>${this.tab==='dataPreview'?`${this.tableHTML()}<div class="pagination"><span>${t('showing')} ${s.rows?this.offset+1:0}–${Math.min(this.offset+this.pageSize,s.rows??0)} / ${fmt(s.rows,0)}</span><div><label>${t('perPage')}<select id="page-size">${[20,50,100].map(n=>`<option ${n===this.pageSize?'selected':''}>${n}</option>`).join('')}</select></label><button class="text-button" data-action="head">${t('head')}</button><button class="text-button" data-action="tail">${t('tail')}</button><button class="button small secondary" data-action="prev-page" ${this.offset?'':'disabled'} aria-label="${t('previous')}">←</button><button class="button small secondary" data-action="next-page" ${this.offset+this.pageSize<s.rows?'':'disabled'} aria-label="${t('next')}">→</button></div></div>`:this.tab==='statistics'?this.profileHTML():`<div class="code-view"><p>${t('codeNote')}</p><pre><code>${esc(s.pandas?.code??t('sourceCode'))}</code></pre><button class="button secondary small" data-export="python">${t('python')}${icon('download')}</button></div>`}</article>`;}
  pipelineHTML(){const nodes=this.snapshot.nodes??[];return `<section class="card pipeline-card"><div class="canvas-heading"><div><span class="eyebrow">REPRODUCIBLE BY DESIGN</span><h2>${t('pipeline')}</h2></div><div><button class="icon-button" data-action="undo" ${this.snapshot.history?.canUndo?'':'disabled'} title="${t('undo')}">↶</button><button class="icon-button" data-action="redo" ${this.snapshot.history?.canRedo?'':'disabled'} title="${t('redo')}">↷</button></div></div><div class="pipeline-nodes">${nodes.map(n=>`<div class="pipeline-node ${this.snapshot.activeId===n.id?'active':''}"><button data-node="${esc(n.id)}"><small>${n.kind==='source'?t('original'):n.inputs.join(' + ')} →</small><strong>${esc(this.name(n.id))}</strong></button>${n.kind==='operation'?`<div><button class="text-button" data-edit="${esc(n.id)}">${t('edit')}</button><button class="text-button" data-delete-node="${esc(n.id)}">${t('remove')}</button>${['group','pivot_table','pivot'].includes(n.spec.type)?`<button class="text-button" data-drill="${esc(n.id)}">${bilingual('下钻原始记录','Drill into source rows')}</button>`:''}</div>`:''}</div>`).join('')}</div></section>`;}
  studioHTML(){return `<div class="studio page-shell wide">${this.intro('studioTitle','studioText',this.exportMenu())}<div class="workspace">${this.datasetPanel()}<div class="work-main">${this.selectionHTML()}${this.statsHTML()}${this.snapshot.activeId?`${this.canvasHTML()}${this.resultsHTML()}`:`<article class="card empty-state"><h2>${t('noDataset')}</h2><button class="button primary" data-action="upload">${t('upload')}</button><button class="button secondary" data-action="add-nba">${t('loadExample')}</button></article>`}</div><aside class="operation-sidebar card"><div class="pane-heading"><h2>${icon('filter')}${t('operation')}</h2><span class="pill">${this.editNode?'EDIT':'23 OPS'}</span></div><p class="hint">${t('operationHint')}</p><div id="operation-form"></div><button class="button primary full" data-action="preview" ${this.snapshot.activeId?'':'disabled'}>${t('preview')}${icon()}</button><div id="operation-preview">${this.previewHTML()}</div></aside></div>${this.pipelineHTML()}</div>`;}
  exportMenu(){return `<details class="export-menu"><summary class="button secondary">${icon('download')}${t('export')}<span>⌄</span></summary><div class="export-options">${['csv','selectionCSV','resultJSON','resultCSV','flow','project','python','svg','png'].map(k=>`<button data-export="${k}" ${k==='selectionCSV'&&!this.selection()?'disabled':''}>${t(k)}</button>`).join('')}<hr><button data-action="restore-flow">${t('restoreFlow')}</button><button data-action="save-local">${t('saveSession')}</button><button data-action="restore-local">${t('restoreSession')}</button><button data-action="clear-local">${t('clearLocal')}</button></div></details>`;}
  mountForm(){if(!this.snapshot.activeId)return;this.form=new OperationForm($('#operation-form'),{columns:this.snapshot.columns,tables:this.snapshot.tables??[],activeId:this.snapshot.activeId,draft:this.draft,charts:ref=>{const col=this.snapshot.profile.columns.find(c=>c.id===ref);return col&&col.q1!==null?{low:col.q1-1.5*(col.q3-col.q1),high:col.q3+1.5*(col.q3-col.q1)}:null;},onChange:()=>{this.preview=null;this.pendingOperation=null;$('#operation-preview').innerHTML='';}});}
  previewHTML(){if(!this.preview)return '';const p=this.preview,r=p.report;return `<div class="preview-result"><h3>${t('changes')}</h3><div class="preview-numbers">${['rows','columns','missing'].map(key=>`<div><small>${t(key)}</small><span>${fmt(r.before[key],0)} → <strong>${fmt(r.after[key],0)}</strong></span></div>`).join('')}${r.invalidRows?`<div><small>${t('invalid')}</small><span>${r.invalidRows.length}</span></div>`:''}</div>${r.edges?`<p class="hint">${t('edges')}: ${r.edges.map(v=>fmt(v,5)).join(' / ')}</p>`:''}${r.unmatchedLeft!==undefined?`<div class="join-report">${['matched','unmatchedLeft','unmatchedRight','expansion'].map(key=>`<p>${t(key)} <strong>${fmt(r[key],2)}</strong></p>`).join('')}</div>`:''}<details><summary>${t('dataPreview')} (${Math.min(8,p.rows)})</summary>${this.tableHTML(p.records,p.columns,false)}</details><details><summary>pandas</summary><pre>${esc(p.pandas?.code??'')}</pre></details><button class="button primary full" data-action="commit">${t('apply')}${icon('check')}</button></div>`;}
  drawActiveCharts(){const data=this.snapshot.charts;if(!data)return;const handlers={locale:getLocale(),title:t(this.chartType),courtMode:this.config.courtMode??'points',onSelection:(channel,predicate)=>this.safe(async()=>{this.channels[channel]=predicate;this.offset=0;await this.analyze();}),onPair:(x,y)=>this.safe(async()=>{this.config.x=x;this.config.y=y;this.chartType='scatter';await this.analyze();}),onField:ref=>{if(this.route==='nba'){this.goto('studio');return;}this.form.type='fillna';this.form.saved=null;this.form.draw();this.form.setField(ref);this.draft=this.form.remember();this.profileDialog(ref);}};
    if($('#main-chart'))renderChart($('#main-chart'),this.chartType,data,handlers);if($('#secondary-chart'))renderChart($('#secondary-chart'),'histogram',data,{...handlers,title:t('distribution')});
  }
  nbaHTML(){const court=this.nbaTab==='courtTab',player=this.nbaTab==='playerTab';return `<div class="nba page-shell">${this.intro('exploreTitle','exploreText',`<button class="button primary" data-action="send-studio">${t('sendStudio')}${icon()}</button>`)}<div class="explore-tabs">${['playerTab','teamTab','trendTab','courtTab'].map((tab,i)=>`<button data-nba-tab="${tab}" class="${tab===this.nbaTab?'active':''}"><span>0${i+1}</span>${t(tab)}</button>`).join('')}<span>${t('dataWindow')}</span></div><div class="nba-controls card"><label>${t(player||court?'choosePlayer':'chooseTeam')}<select id="nba-entity"><option value="">${t(player||court?'allPlayers':'allTeams')}</option>${(this.nbaValues??[]).filter(v=>v.value!==null).sort((a,b)=>String(a.value).localeCompare(String(b.value))).map(v=>`<option value="${esc(v.value)}" ${this.channels.entity?.value===v.value?'selected':''}>${esc(court?this.playerNames?.get(v.value)??v.value:v.value)}</option>`).join('')}</select></label><label>${t('metric')}<select id="nba-metric">${(court?['shot_distance','shot_value']:['pts','ast','reb','stl','blk','tov','fg_pct']).map(v=>`<option ${v===this.config.metric?'selected':''}>${v}</option>`).join('')}</select></label>${!court?`<label>${t('aggregate')}<select data-config="aggregate">${['mean','sum','max','std'].map(fn=>`<option value="${fn}" ${fn===this.config.aggregate?'selected':''}>${t(fn)}</option>`).join('')}</select></label>`:''}<div class="nba-scope"><i class="dot"></i>${player?t('actualPlayed'):t('snapshotNote')}</div></div>${this.selectionHTML()}${this.statsHTML()}<div class="nba-chart-layout"><div>${this.canvasHTML()}</div><aside class="card nba-notebook"><span class="eyebrow">READ THE DATA</span><h2>${bilingual('用问题驱动分析','Let questions guide you')}</h2><p>${court?t('coordinateNote'):player?bilingual('刷选得分与助攻，观察哪些球员记录落入选区。统计基于实际出场记录；场均榜单在总览中限定至少 5 场。','Brush points and assists to compare played appearances. The overview leaderboard requires at least five appearances.'):bilingual('球队逐场记录可以按比赛日聚合。选择球队后，查看得分走势与波动，再把条件送入工作台继续分析。','Aggregate team game records by date. Choose a team, inspect scoring and variation, then continue with the same conditions in Studio.')}</p><div class="notebook-divider"></div><span class="label">${t('scope')}</span><strong>01 — 30 NOV 2025</strong><p>${t('snapshotNote')}</p>${court?`<div class="notebook-divider"></div><span class="label">${t('attempts')} / ${t('made')}</span><strong>${fmt(this.snapshot.charts?.shots?.attempts,0)} / ${fmt(this.snapshot.charts?.shots?.made,0)}</strong><p>${t('lowN')}</p>`:''}<button class="button secondary full" data-action="about">${t('dataLimits')}↗</button></aside></div>${this.resultsHTML()}</div>`;}
  galleryHTML(){return `<div class="gallery page-shell">${this.intro('galleryTitle','galleryText',`<button class="button secondary" data-action="go-studio">${t('openStudio')}${icon()}</button>`)}<div class="gallery-data card"><span>${icon('database')} ${t('currentData')} <strong>${esc(this.snapshot.activeId?this.name(this.snapshot.activeId):'—')}</strong></span><span>${fmt(this.snapshot.rows,0)} ${t('rows')} · ${t('allDataHint')}</span></div><div class="gallery-encodings card">${this.encodings()}</div><div class="gallery-grid">${CHARTS.map((type,i)=>`<article class="card gallery-card"><div class="canvas-heading"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} / VISUAL ANALYSIS</span><h2>${t(type==='missing'?'missingChart':type)}</h2></div><span class="chart-number">↗</span></div><div class="chart-host gallery-chart" id="gallery-${type}"></div><p class="hint">${t(({scatter:'numericTwo',bar:'categoryAny',line:'dateNumeric',histogram:'numericOne',box:'numericOne',correlation:'numericMany',heatmap:'requiresPivot',area:'dateNumeric',distribution:'numericOne',court:'requiresShots',missing:'anyTable'})[type])}</p><button class="button secondary full" data-use-chart="${type}" ${type==='court'&&!this.canCourt()?'disabled':''}>${t('useChart')}${icon()}</button></article>`).join('')}</div></div>`;}
  drawGallery(){for(const type of CHARTS){if(type==='court'&&!this.canCourt()){$(`#gallery-${type}`).innerHTML=`<p class="empty-state">${t('requiresShots')}</p>`;continue;}renderChart($(`#gallery-${type}`),type,this.snapshot.charts,{locale:getLocale(),title:t(type==='missing'?'missingChart':type)});}}
  filterFields(value){$$('[data-field][data-name]').forEach(el=>el.hidden=!el.dataset.name.includes(value.toLowerCase()));}
  view(){return {config:this.config,chartType:this.chartType,channels:this.channels,tab:this.tab,locale:getLocale(),pageSize:this.pageSize};}
  activeSources(){const nodes=new Map((this.snapshot.nodes??[]).map(n=>[n.id,n])),sources=[],seen=new Set();const visit=id=>{if(seen.has(id))return;seen.add(id);const node=nodes.get(id);if(node?.kind==='source')sources.push({sourceId:node.sourceId,fileName:this.snapshot.tables?.find(t=>t.id===id)?.provenance?.fileName??node.sourceId});else for(const input of node?.inputs??[])visit(input);};visit(this.snapshot.activeId);return sources;}
  canCourt(){const cols=this.snapshot.columns??[];return ['x_legacy','y_legacy'].every(name=>cols.some(c=>c.name===name&&['integer','number'].includes(c.type)))&&cols.some(c=>c.name==='made'&&c.type==='boolean')&&this.activeSources().some(s=>s.sourceId==='nba_shots');}
  sourceCaption(){const sources=this.activeSources(),nba=sources.some(s=>s.sourceId.startsWith('nba_')),names=sources.filter(s=>!s.sourceId.startsWith('nba_')).map(s=>s.fileName).join(' + ');return `${nba?'SportsDataverse / NBA · Nov 2025':''}${nba&&names?' + ':''}${names}${this.chartType==='court'?' · legacy units: 0.1 ft':''}`.slice(0,145);}
  predicateLabel(a){if(a.op==='and'||a.op==='or')return a.args.map(p=>this.predicateLabel(p)).join(a.op==='and'?' ∧ ':' ∨ ');if(a.op==='not')return `¬ (${this.predicateLabel(a.arg)})`;const name=this.snapshot.columns?.find(c=>c.id===a.field||c.name===a.field)?.name??a.field;if(a.op==='between')return `${name} ∈ [${fmt(a.min,2)}, ${fmt(a.max,2)}]`;return `${name} ${t(a.op)} ${a.values?.join(', ')??a.value??''}`;}
  restoreView(view){this.channels=view?.channels??{};if(view?.config)this.config=view.config;if(CHARTS.includes(view?.chartType))this.chartType=view.chartType;if(['dataPreview','statistics','pandas'].includes(view?.tab))this.tab=view.tab;this.offset=0;}
  drawPreview(){const host=$('#operation-preview');if(!this.preview||!host)return;const {report,beforeCharts,charts}=this.preview;const type=this.pendingOperation?.spec.type;
    const graph=document.createElement('div');graph.className='preview-graphs';host.prepend(graph);
    if(type==='merge'){graph.innerHTML=`<p class="hint">${t('joinPreview')}</p><div id="join-preview-chart" class="chart-host"></div>`;renderChart($('#join-preview-chart'), 'bar',{bars:['matched','unmatchedLeft','unmatchedRight'].map(key=>({key:t(key),value:report[key],count:report[key]})),fields:{metric:{name:t('rows')}}},{locale:getLocale(),title:t('joinPreview')});}
    else if(type==='group'||type.startsWith('pivot')){graph.innerHTML=`<p class="hint">${t('after')} · ${t('allDataHint')}</p><div id="result-preview-chart" class="chart-host"></div>`;renderChart($('#result-preview-chart'),type.startsWith('pivot')?'heatmap':'bar',charts,{locale:getLocale(),title:t(type)});}
    else{graph.innerHTML=`<p class="hint">${t('before')}</p><div id="before-preview-chart" class="chart-host"></div><p class="hint">${t('after')}</p><div id="after-preview-chart" class="chart-host"></div>`;renderChart($('#before-preview-chart'),beforeCharts.histogram.length?'histogram':'missing',beforeCharts,{locale:getLocale(),title:t('before')});renderChart($('#after-preview-chart'),charts.histogram.length?'histogram':'missing',charts,{locale:getLocale(),title:t('after')});}
    if(type==='dedup'){const button=document.createElement('button');button.className='text-button';button.textContent=bilingual('检查重复记录与保留结果','Inspect duplicate rows and retention');graph.append(button);button.onclick=()=>this.safe(async()=>{const d=await this.worker.call('duplicates',this.pendingOperation.spec.params);this.dialog(t('dedup'),`<p>${t('affected')}: ${d.count} · ${bilingual('最多显示前 30 条待移除记录','First 30 rows marked for removal')}</p>${this.tableHTML(d.records,d.columns,false)}`);});}
  }
  click(event){const button=event.target.closest('button');if(!button)return;const d=button.dataset;if(button.disabled)return;if(this.busyCount&&d.action!=='cancel')return;
    this.safe(async()=>{
      if(d.action){switch(d.action){
        case 'locale':this.preserveDraft();setLocale(getLocale()==='zh-CN'?'en-US':'zh-CN');this.render();return;
        case 'go-nba':this.goto('nba');return;case 'go-studio':this.goto('studio');return;
        case 'upload':this.filePicker('.csv,.tsv,.json,.xlsx',file=>this.openImport(file));return;
        case 'add-nba':this.nbaDialog();return;
        case 'about':this.aboutDialog();return;
        case 'clear-selection':this.channels={};this.offset=0;await this.analyze();return;
        case 'apply-selection':if(this.selection())await this.mutate('commit',{spec:{type:'filter',params:{predicate:this.selection()}}});return;
        case 'preview':if(this.selection()){this.toast(t('applyFirst'),true);return;}this.pendingOperation=this.form.read();this.preview=await this.worker.call('preview',this.pendingOperation);$('#operation-preview').innerHTML=this.previewHTML();this.drawPreview();return;
        case 'commit':if(!this.pendingOperation||!this.preview)return;await this.mutate('commit',this.pendingOperation);this.toast(t('done'));return;
        case 'undo':case 'redo':this.draft=null;await this.mutate(d.action);return;
        case 'prev-page':this.offset=Math.max(0,this.offset-this.pageSize);await this.analyze();return;
        case 'next-page':this.offset+=this.pageSize;await this.analyze();return;
        case 'head':this.offset=0;await this.analyze();return;
        case 'tail':this.offset=Math.max(0,(this.snapshot.rows??0)-this.pageSize);await this.analyze();return;
        case 'chart-svg':case 'chart-png':await this.export(d.action.slice(6));return;
        case 'send-studio':if(this.selection())await this.mutate('commit',{spec:{type:'filter',params:{predicate:this.selection()}}});this.draft=null;this.goto('studio');return;
        case 'cancel':await this.worker.cancel();this.channels={};await this.analyze();this.toast(errorText({code:'CANCELLED'}));return;
        case 'restore-flow':this.filePicker('.json',file=>this.restoreFile(file));return;
        case 'save-local':await localProject('put',{...await this.worker.call('checkpoint'),view:this.view()});this.toast(t('saved'));return;
        case 'restore-local':{const data=await localProject('get');if(!data)throw new Error('NO_LOCAL_PROJECT');await this.worker.call('recover',data);this.loaded=new Set(data.flow.sources.filter(s=>s.sourceId.startsWith('nba_')).map(s=>s.sourceId.slice(4)));this.restoreView(data.view);this.draft=null;await this.worker.retain();this.goto('studio');await this.analyze();this.toast(t('restored'));return;}
        case 'clear-local':await localProject('delete');this.toast(bilingual('本机保存已清除','Local save cleared'));return;
      }}
      if(d.node){this.channels={};this.offset=0;this.draft=null;this.preview=null;await this.worker.call('select',{id:d.node});await this.analyze();return;}
      if(d.removeSource){await this.mutate('removeSource',{id:d.removeSource});this.loaded.delete(d.removeSource.replace('nba_',''));return;}
      if(d.deleteNode){await this.mutate('removeNode',{id:d.deleteNode});return;}
      if(d.edit){this.editDialog(d.edit);return;}
      if(d.drill){await this.drillDialog(d.drill);return;}
      if(d.field){this.profileDialog(d.field);return;}if(d.clearChannel){delete this.channels[d.clearChannel];this.offset=0;await this.analyze();return;}
      if(d.sort){if(this.selection()){this.toast(t('applyFirst'),true);return;}const ascending=this.lastSort?.field===d.sort?!this.lastSort.ascending:true;this.lastSort={field:d.sort,ascending};await this.mutate('commit',{spec:{type:'sort',params:{by:[d.sort],ascending}}});return;}
      if(d.tab){this.tab=d.tab;this.preserveDraft();this.render();return;}
      if(d.export){await this.export(d.export);return;}
      if(d.nbaTab){this.nbaTab=d.nbaTab;this.nbaValues=[];await this.activateNBA();return;}
      if(d.useChart){this.chartType=d.useChart;this.goto('studio');return;}
      if(d.question){if(d.question==='upload'){this.filePicker('.csv,.tsv,.json,.xlsx',file=>this.openImport(file));return;}this.nbaTab=d.question==='court'?'courtTab':'playerTab';this.goto('nba');return;}
      if(d.leader){this.nbaTab='playerTab';this.pendingNBASelection={entity:{op:'eq',field:'player_name',value:d.leader}};this.goto('nba');return;}
    });
  }
  change(event){const el=event.target;if(this.busyCount)return;
    if(el.dataset.config){this.safe(async()=>{this.preserveDraft();this.config[el.dataset.config]=el.multiple?[...el.selectedOptions].map(o=>o.value):el.type==='number'?Number(el.value):el.value;this.offset=0;await this.analyze();});return;}
    if(el.id==='chart-type'){this.preserveDraft();this.chartType=el.value;if(this.chartType==='court')this.safe(()=>this.analyze());else this.render();return;}
    if(el.id==='page-size'){this.safe(async()=>{this.pageSize=Number(el.value);this.offset=0;await this.analyze();});return;}
    if(el.id==='nba-entity'){this.safe(async()=>{this.channels.entity=el.value?{op:'eq',field:this.nbaTab==='courtTab'?'player_id':this.nbaTab==='playerTab'?'player_name':'team_abbr',value:el.value}:null;this.offset=0;await this.analyze();});return;}
    if(el.id==='nba-metric'){this.safe(async()=>{this.config.metric=el.value;if(this.chartType!=='court')this.config.x=el.value;await this.analyze();});}
  }
  filePicker(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>input.files[0]&&this.safe(()=>callback(input.files[0]));input.click();}
  dialog(title,body,bind){$('#datalab-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='datalab-dialog';dialog.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="${t('close')}">×</button></div><div class="dialog-content">${body}</div>`;document.body.append(dialog);$('[data-close]',dialog).onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.showModal();bind?.(dialog);return dialog;}
  async openImport(file){this.importData=await readUpload(file);this.importTypes=null;await this.importDialog();}
  async importDialog(){const data=this.importData;data.sheetIndex??=0;const text=data.sheets?.[data.sheetIndex].text??data.text,options={format:data.format,fileName:data.fileName,...data.options,types:this.importTypes??undefined};const prepared=await this.worker.call('prepare',{text,options});this.importTypes=Object.fromEntries(prepared.schema.map(c=>[c.name,c.type]));
    this.dialog(t('importTitle'),`<p>${t('importNote')}</p><div class="import-file-label">${icon('database')}<strong>${esc(data.fileName)}</strong><span>${fmt(prepared.rowCount,0)} ${t('rows')} · ${prepared.schema.length} ${t('columns')}</span></div>${data.sheets?`<label>${t('sheet')}<select id="import-sheet">${data.sheets.map((s,i)=>`<option value="${i}" ${i===data.sheetIndex?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`:''}<div class="import-options">${data.format!=='json'?`<label>${t('delimiter')}<select id="import-delimiter">${[[',',bilingual('逗号 ,','Comma ,')],['\t',bilingual('制表符','Tab')],[';',bilingual('分号 ;','Semicolon ;')],['|','|']].map(([v,name])=>`<option value="${esc(v)}" ${v===(data.options?.delimiter??(data.format==='tsv'?'\t':','))?'selected':''}>${name}</option>`).join('')}</select></label>`:''}<label>${t('nullTokens')}<input id="null-tokens" value="${esc(data.options?.nullTokens?.join(',')??'')}"></label></div><div class="import-types">${prepared.schema.map(c=>`<label>${esc(c.name)}<select data-type-field="${esc(c.name)}">${['string','category','number','integer','boolean','date','datetime'].map(type=>`<option value="${type}" ${c.type===type?'selected':''}>${t(type==='date'?'dateType':type==='category'?'categoryType':type)}</option>`).join('')}</select></label>`).join('')}</div>${prepared.errors.length?`<div class="inline-error" role="alert">${t('invalidWarning')} (${prepared.errors.length})<details><summary>${t('invalid')}</summary><pre>${esc(JSON.stringify(prepared.errors.slice(0,8),null,2))}</pre></details></div>`:''}${this.tableHTML(prepared.preview,prepared.schema,false)}<label class="check"><input id="import-coerce" type="checkbox">${t('coerce')}</label><p class="hint">${t('localPrivacy')} · ${t('importFormat')}</p><div class="dialog-actions"><button id="confirm-import" class="button primary">${t('confirmImport')}${icon()}</button></div>`,dialog=>{
      $$('[data-type-field]',dialog).forEach(el=>el.onchange=()=>this.safe(async()=>{this.importTypes[el.dataset.typeField]=el.value;await this.importDialog();}));
      $('#import-sheet',dialog)?.addEventListener('change',e=>this.safe(async()=>{data.sheetIndex=+e.target.value;this.importTypes=null;await this.importDialog();}));
      const updateParse=()=>{data.options={delimiter:$('#import-delimiter',dialog)?.value,nullTokens:$('#null-tokens',dialog).value.split(',').map(v=>v.trim()).filter(Boolean)};this.importTypes=null;this.safe(()=>this.importDialog());};
      $('#import-delimiter',dialog)?.addEventListener('change',updateParse);$('#null-tokens',dialog).onchange=updateParse;
      $('#confirm-import',dialog).onclick=()=>this.safe(async()=>{const opts={...options,types:this.importTypes,errors:$('#import-coerce',dialog).checked?'coerce':'raise'};await this.worker.call('import',{text,options:opts});await this.worker.retain();this.channels={};this.config={correlation:true,aggregate:'mean'};this.draft=null;this.offset=0;this.preview=null;dialog.close();this.route='studio';location.hash='/studio';await this.analyze();});
    });
  }
  async restoreFile(file){if(file.size>50*1024*1024)throw new Error('FILE_LIMIT');const data=JSON.parse(await file.text());if(data.sources?.[0]?.records){await this.worker.call('recover',data);this.loaded=new Set(data.flow.sources.filter(s=>s.sourceId.startsWith('nba_')).map(s=>s.sourceId.slice(4)));}else{const missing=data.sources?.filter(s=>s.sourceId.startsWith('nba_')&&!this.loaded.has(s.sourceId.slice(4))).map(s=>s.sourceId.slice(4))??[];if(missing.length)await this.loadNBA(missing);await this.worker.call('restore',{flow:data});}this.restoreView(data.view);this.draft=null;await this.worker.retain();this.goto('studio');await this.analyze();this.toast(t('restored'));}
  nbaDialog(){this.dialog(t('addNBA'),`<p>${t('snapshotNote')}</p><div class="nba-source-list">${this.manifest.tables.map(table=>`<button class="source-choice" data-source="${table.id}"><span>${NBA_LABELS[table.id][getLocale()==='zh-CN'?0:1]}<small>${esc(table.file)}</small></span><strong>${fmt(table.rows,0)}<small>${t('rows')}</small></strong>${icon()}</button>`).join('')}</div>`,dialog=>$$('[data-source]',dialog).forEach(el=>el.onclick=()=>this.safe(async()=>{await this.loadNBA([el.dataset.source]);this.channels={};this.draft=null;await this.worker.call('select',{id:`source:nba_${el.dataset.source}`});if(el.dataset.source==='shots'){this.config={x:'x_legacy',y:'y_legacy',metric:'shot_distance',date:'game_date',category:'made',aggregate:'mean'};this.chartType='court';}await this.worker.retain();dialog.close();await this.analyze();})));}
  aboutDialog(){this.dialog(t('about'),`<div class="about-grid"><div><span class="eyebrow">FROZEN DATA / TRANSPARENT SOURCES</span><h3>${t('dataWindow')}</h3><p>${t('snapshotNote')}</p><p>${t('sourceAttribution')}</p><a href="https://github.com/sportsdataverse/sportsdataverse-data" target="_blank" rel="noreferrer">SportsDataverse data repository ↗</a><p>${t('coordinateNote')}</p><a href="https://sdvplotr.sportsdataverse.org/reference/sdv_court_coords.html" target="_blank" rel="noreferrer">SportsDataverse coordinate definition ↗</a><p>${bilingual('官方 PDF 抽查 3 场、81 项数值匹配；不代表全量独立验证。原点坐标保留，6 次超半场投篮保留，分钟 :60 按进位处理并保留原值。','Three official NBA game books: 81 numeric checks matched. This is sample verification, not independent validation of every event. Origin coordinates and six beyond-half-court heaves are retained. Rounded :60 minutes are carried while raw values remain available.')}</p></div><div><h3>${t('localPrivacy')}</h3><p>${t('offlineNote')}</p><p>${t('localSaveNote')}</p><h3>${bilingual('来源署名与许可标记','Attribution and license notices')}</h3><p>${bilingual('SportsDataverse README 标记 CC BY 4.0，其软件 LICENSE 为 MIT；NBA 上游数据适用条款另有约束，再分发适用范围尚待确认。此处逐项披露来源事实，不宣称 NBA 授权或背书。','SportsDataverse README carries a CC BY 4.0 badge; its software LICENSE is MIT. Upstream NBA terms contain additional restrictions; redistribution applicability remains under review. These are disclosed source facts, not a claim of NBA authorization or endorsement.')}</p><div class="source-links"><a href="https://github.com/sportsdataverse/sportsdataverse-data/blob/c30618f5f439abc8275f0a9bea30892a598890b8/README.md" target="_blank" rel="noreferrer">Publisher notice ↗</a><a href="https://www.nba.com/termsofuse" target="_blank" rel="noreferrer">NBA Terms of Use ↗</a></div><p>${t('licenseNote')}</p><button class="button secondary" id="manifest-download">${bilingual('下载数据清单与哈希','Download manifest and hashes')}${icon('download')}</button></div></div>`,dialog=>$('#manifest-download',dialog).onclick=()=>download(this.manifest,'nba-source-manifest.json'));}
  profileDialog(ref){const c=this.snapshot.profile?.columns.find(c=>c.id===ref);if(!c)return;this.dialog(`${t('profileField')} · ${c.name}`,`<div class="field-profile-header"><span class="pill">${c.type}</span><strong>${fmt(c.count,0)} ${t('valid')}</strong><span>${fmt(c.missing,0)} ${t('missing')} (${fmt(c.missingRate===null?null:c.missingRate*100,1)}%)</span><span>${fmt(c.unique,0)} ${t('unique')}</span></div>${c.values?`<h3>${t('topValues')} · ${bilingual('最多显示 30 项，导出包含全部','Showing up to 30; export includes all')}</h3><div class="frequency-list">${c.values.slice(0,30).map(v=>`<div><span>${esc(v.value??t('na'))}</span><div class="frequency-bar" style="--width:${v.proportion*100}%"></div><strong>${fmt(v.count,0)}</strong><small>${fmt(v.proportion*100,1)}%</small></div>`).join('')}</div>`:`<div class="field-stat-grid">${['mean','var','std','min','q1','median','q3','max'].map(key=>`<div><small>${t(key)}</small><strong>${fmt(c[key],4)}</strong></div>`).join('')}</div>`}${!c.values?`<div class="quantile-query"><label>${bilingual('分位数 q（0–1）','Quantile q (0–1)')}<input type="number" id="quantile-q" min="0" max="1" step=".01" value=".25"></label><button id="query-quantile" class="button secondary small">${bilingual('计算分位数','Calculate quantile')}</button><strong id="quantile-result">${fmt(c.q1,4)}</strong></div>`:''}<div class="dialog-actions"><button id="field-clean" class="button secondary">${t('fillna')}</button><button id="field-frequency" class="button secondary">${t('resultCSV')}${icon('download')}</button></div>`,dialog=>{if($('#query-quantile',dialog))$('#query-quantile',dialog).onclick=()=>this.safe(async()=>{$('#quantile-result',dialog).textContent=fmt(await this.worker.call('quantile',{field:ref,q:Number($('#quantile-q',dialog).value),selection:this.selection()}),5);});$('#field-clean',dialog).onclick=()=>{dialog.close();if(this.route!=='studio'){this.draft={type:'fillna',values:{field:ref}};this.goto('studio');}else{this.form.type='fillna';this.form.saved=null;this.form.draw();this.form.setField(ref);this.form.host.scrollIntoView({block:'center',behavior:'smooth'});}};$('#field-frequency',dialog).onclick=()=>this.safe(async()=>download(asCSV(await this.worker.call('analysisExport',{kind:'frequencies',fields:[ref],selection:this.selection()})),`${c.name}-frequencies.csv`,'text/csv'));});}
  editDialog(id){const node=this.snapshot.nodes.find(n=>n.id===id);if(!node)return;this.dialog(`${t('edit')} · ${t(node.spec.type)}`,`<p>${bilingual('修改已保存的操作参数。预览通过后再应用，系统会原子重算所有依赖步骤；失败时保留原流程。字段使用稳定 ID。','Edit saved operation parameters. Preview before applying. All dependent steps are recomputed atomically; a failure preserves the original flow. Fields use stable IDs.')}</p><textarea id="edit-spec" class="json-editor" rows="14" spellcheck="false">${esc(JSON.stringify(node.spec,null,2))}</textarea><div id="edit-report"></div><div class="dialog-actions"><button id="preview-edit" class="button secondary">${t('preview')}</button><button id="apply-edit" class="button primary" disabled>${t('apply')}</button></div>`,dialog=>{let spec;$('#edit-spec',dialog).oninput=()=>{$('#apply-edit',dialog).disabled=true;};$('#preview-edit',dialog).onclick=()=>this.safe(async()=>{spec=JSON.parse($('#edit-spec',dialog).value);const preview=await this.worker.call('preview',{spec,inputs:node.inputs});$('#edit-report',dialog).textContent=`${t('rows')}: ${preview.report.before.rows} → ${preview.rows} · ${t('columns')}: ${preview.report.before.columns} → ${preview.columns.length}`;$('#apply-edit',dialog).disabled=false;});$('#apply-edit',dialog).onclick=()=>this.safe(async()=>{await this.mutate('edit',{id,spec});dialog.close();this.toast(t('done'));});});}
  async drillDialog(id){const node=this.snapshot.nodes.find(n=>n.id===id);await this.worker.call('select',{id});const records=await this.worker.call('analysisExport',{kind:'rows'}),table=this.snapshot.tables.find(t=>t.id===id),input=this.snapshot.tables.find(t=>t.id===node.inputs[0]),keys=node.spec.params.keys??node.spec.params.index;const keyRefs=Array.isArray(keys)?keys:[keys],keyCols=keyRefs.map(ref=>input.columns.find(c=>c.id===ref||c.name===ref));
    this.dialog(bilingual('下钻原始记录','Drill into source rows'),`<p>${bilingual('从聚合键构造筛选，回到聚合步骤的输入记录。','Build predicates from aggregation keys and return to rows before aggregation.')}</p><label>${t('groupKeys')}<select id="drill-row">${records.map((r,i)=>`<option value="${i}">${esc(keyCols.map(c=>`${c.name}: ${r[c.name]??t('na')}`).join(' / '))}</option>`).join('')}</select></label>${node.spec.type.startsWith('pivot')?`<label>${t('columnKeys')}<select id="drill-column"><option value="">${bilingual('全部列组合','All column combinations')}</option>${table.columns.filter(c=>c.pivotValues).map(c=>`<option value="${esc(c.id)}">${esc(c.pivotValues.join(' / '))}</option>`).join('')}</select></label>`:''}<div class="dialog-actions"><button id="drill-apply" class="button primary">${t('goStudio')}${icon()}</button></div>`,dialog=>{$('#drill-apply',dialog).disabled=!records.length;$('#drill-apply',dialog).onclick=()=>this.safe(async()=>{const r=records[+$('#drill-row',dialog).value],args=keyCols.map(c=>r[c.name]===null?{op:'isMissing',field:c.id}:{op:'eq',field:c.id,value:r[c.name]});const selected=$('#drill-column',dialog)?.value;if(selected){const values=table.columns.find(c=>c.id===selected).pivotValues;const refs=Array.isArray(node.spec.params.columns)?node.spec.params.columns:[node.spec.params.columns];refs.forEach((ref,i)=>args.push(values[i]===null?{op:'isMissing',field:ref}:{op:'eq',field:ref,value:values[i]}));}await this.mutate('commit',{spec:{type:'filter',params:{predicate:and(args)}},inputs:node.inputs.slice(0,1)});dialog.close();this.goto('studio');});});
  }
  async export(kind){if(!this.snapshot.activeId)throw new Error('SELECT_FIRST');const name=`datalab-${this.snapshot.activeId.replace(':','-')}`;
    if(['svg','png'].includes(kind)){const host=$('#main-chart');if(!host)throw new Error('NO_CHART');download(await exportChart(host,kind,`${t(this.chartType)} · ${this.name(this.snapshot.activeId)}`,`${this.snapshot.rows} ${t('rows')} · ${this.sourceCaption()||t('currentData')} · ${new Date().toISOString().slice(0,10)}`),`${name}.${kind}`);}
    else if(kind==='csv'||kind==='selectionCSV')download(await this.worker.call('csv',{selection:kind==='selectionCSV'?this.selection():null}),`${name}${kind==='selectionCSV'?'-selection':''}.csv`,'text/csv');
    else if(kind==='flow')download({...await this.worker.call('flow'),view:this.view()},`${name}-flow.json`);
    else if(kind==='project')download({...await this.worker.call('checkpoint'),view:this.view()},`${name}-project.json`);
    else if(kind==='python')download(await this.worker.call('pandas'),`${name}.py`,'text/x-python');
    else{const fields=this.snapshot.columns.filter(c=>['number','integer'].includes(c.type)).map(c=>c.id).slice(0,12);const records=await this.worker.call('analysisExport',{kind:this.chartType==='correlation'?'correlation':'rows',fields,selection:this.selection()});download(kind==='resultCSV'?asCSV(records):{dataset:this.snapshot.activeId,selection:this.selection(),profile:this.snapshot.profile,provenance:this.snapshot.provenance,sources:this.activeSources(),nbaManifest:this.activeSources().some(s=>s.sourceId.startsWith('nba_'))?this.manifest:undefined,records},`${name}-analysis.${kind==='resultCSV'?'csv':'json'}`,kind==='resultCSV'?'text/csv':'application/json');}
    this.toast(t('downloaded'));
  }
}
